import{_ as o,c as n,o as r,ag as t}from"./chunks/framework.Ds6Eueu6.js";const m=JSON.parse('{"title":"Prologue","description":"","frontmatter":{},"headers":[],"relativePath":"master/prologue/introduction.md","filePath":"master/prologue/introduction.md","lastUpdated":1786514321000}'),a={name:"master/prologue/introduction.md"};function i(s,e,l,u,c,d){return r(),n("div",null,e[0]||(e[0]=[t('<h1 id="prologue" tabindex="-1">Prologue <a class="header-anchor" href="#prologue" aria-label="Permalink to &quot;Prologue&quot;">​</a></h1><h2 id="introduction-to-aureuserp" tabindex="-1">Introduction to AureusERP <a class="header-anchor" href="#introduction-to-aureuserp" aria-label="Permalink to &quot;Introduction to AureusERP&quot;">​</a></h2><p><a href="https://aureuserp.com/" target="_blank" rel="noreferrer">AureusERP</a> is a powerful, open-source Enterprise Resource Planning (ERP) solution designed to meet the needs of Small and Medium Enterprises (SMEs) as well as large-scale organizations. Built on <strong>Laravel 13</strong>, the most popular PHP framework, and <strong>FilamentPHP 5</strong>, a dynamic resource management library, AureusERP offers an extensible and developer-friendly platform for streamlining business operations.</p><h2 id="key-features" tabindex="-1">Key Features <a class="header-anchor" href="#key-features" aria-label="Permalink to &quot;Key Features&quot;">​</a></h2><ul><li><strong>Powered by Laravel 13</strong>: Ensures security, reliability, and scalability, making it ideal for enterprise-level applications.</li><li><strong>Enhanced with FilamentPHP 5</strong>: Delivers an intuitive admin panel, modular forms, and dynamic resource management for seamless interaction.</li><li><strong>Highly Modular Design</strong>: Allows effortless integration of modules for finance, HR, inventory, manufacturing, maintenance, CRM, and more, catering to diverse business needs.</li><li><strong>Multi-Company Support</strong>: Manage multiple companies from a single installation, with company scoping, allowed-companies access control, and a built-in company switcher.</li><li><strong>Open-Source &amp; Extensible</strong>: Freely available for use, modification, and extension, encouraging innovation within the developer community.</li><li><strong>Enterprise-Ready Scalability</strong>: Designed to support complex workflows and business processes, making it adaptable to growing enterprises.</li></ul><h2 id="why-choose-aureuserp" tabindex="-1">Why Choose AureusERP? <a class="header-anchor" href="#why-choose-aureuserp" aria-label="Permalink to &quot;Why Choose AureusERP?&quot;">​</a></h2><ul><li><strong>Modern Technology Stack</strong>: Combines Laravel 13&#39;s backend robustness with FilamentPHP 5&#39;s efficiency, running on PHP 8.3+, for an optimal user experience.</li><li><strong>Developer-Centric Architecture</strong>: Features clean code, modular structure, and comprehensive documentation to support customization and expansion.</li><li><strong>User-Friendly Interface</strong>: Built with <strong>TailwindCSS</strong> for a responsive, visually appealing, and intuitive UI.</li><li><strong>Scalable &amp; Customizable</strong>: Easily tailored to fit the unique operational requirements of businesses of all sizes.</li><li><strong>Community-Driven Innovation</strong>: Supported by an active open-source community, fostering continuous improvements, contributions, and support.</li></ul><p>AureusERP is your gateway to an efficient, scalable, and highly customizable enterprise solution. Join the community and revolutionize the way you manage your business today!</p>',8)]))}const g=o(a,[["render",i]]);export{m as __pageData,g as default};
